# Generated by build.py from recipe.yml for recipe http-serve-two-folders-as-shares. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'docs', 'data' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'docs/guide.txt'), "Read me first.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'data/a.txt'), "first`n")
[IO.File]::WriteAllText((Join-Path $PWD 'up.txt'), "uploaded`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--allow-uploads', '--share', '"docs=docs;readonly"', '--share', 'data=data', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s http://127.0.0.1:8080/docs/guide.txt http://127.0.0.1:8080/data/a.txt } finally { Stop-Process $server0 }
